        PythStructs.Price memory price = fetchPrice(feedIndex, updateData);
        uint256 totalPriceUSD = packages[_index].price * _quantity;

        int64 priceValue = price.price;
        require(priceValue > 0, "Invalid price feed value");

        uint256 requiredCrypto = (totalPriceUSD * 10 ** 18) /
            uint256(uint64(priceValue));

        require(msg.value >= requiredCrypto, "Insufficient crypto sent");

        finalizePurchase(_index, _quantity);
    }

    // TODO
    function finalizePurchase(uint256 _index, uint256 _quantity) internal {
        contractBalance += packages[_index].price * _quantity;
        emit PurchaseEvent(msg.sender, _index, _quantity);
    }

    /**
     * @dev Withdraw funds to the vault using call.
     * @param _amount uint256 The amount to withdraw.
     */
    function withdraw(uint256 _amount) external onlyOwner {
        contractBalance -= _amount;

        (bool success, ) = vaultAddress.call{value: _amount}("");
        require(success, "Withdraw was not successful");
    }

    /**
     * @dev Withdraw all the funds to the vaultAdress using call.
     */
    function withdrawAll() external onlyOwner {
        uint256 _amount = contractBalance;
        contractBalance = 0;

        (bool success, ) = vaultAddress.call{value: _amount}("");
        require(success, "Withdraw all was not successful");
    }
}

